<script setup>
import { Table as SharedTable } from "@itpmining/vue-basic-components";
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useI18n} from 'vue-i18n'
import {Button,Icon,MenuItem,Modal,TextInput,Select} from '@itpmining/vue-basic-components'
import Sidebar from '@/components/mroCommercial/MroAdminSidebar.vue'
import ThemeSwitcher from '@/components/mroCommercial/MroThemeSwitcher.vue'
import MroBrand from '@/components/mroCommercial/MroBrand.vue'
import PlanEditor from '@/components/admin/PlanEditor.vue'
import BillingEditor from '@/components/admin/BillingEditor.vue'
import LegalEditor from '@/components/admin/LegalEditor.vue'
import InvoiceEditor from '@/components/admin/InvoiceEditor.vue'
import api from '@/api/mroCommercialAdapter'
const {t,locale}=useI18n(),route=useRoute(),router=useRouter()
const query=ref(''),verified=ref(''),sort=ref('created_at'),rows=ref([]),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),overview=ref(null),detail=ref(null),users=ref([]),userPage=ref(1),userLastPage=ref(1),plans=ref([]),editor=ref(null),supplier=ref({}),organizationOptions=ref([]),assignVersion=ref(''),assignEnd=ref(''),grantUser=ref(''),grantPermission=ref('companies.read'),confirmation=ref(null),approvalNote=ref(''),proofs=ref(null)
let revision=0,searchTimer
const permission=p=>overview.value?.permissions?.some(v=>v==='platform.manage'||v===p)
const sections=computed(()=>[['companies','companies.read','Business'],['plans','plans.read','Grid'],['payments','billing.read','pdf'],['documents','legal.read','Read'],['consents','legal.read','Timeline'],['access','platform.manage','Lock']].filter(s=>permission(s[1])))
const section=computed(()=>sections.value.find(s=>s[0]===route.params.section)?.[0]||sections.value[0]?.[0]||'companies')
const title=computed(()=>t('adminPortal.'+section.value))
const heading=computed(()=>({companies:['organization','email','verified','users','companies','plan','storage','status','createdAt'],plans:['code','name','version','status','price','visibility'],payments:['number','organization','status','total','due_date'],documents:['title','documentType','language','version','status','effectiveAt'],consents:['email','title','version','acceptance','createdAt'],access:['email','permission','createdAt']})[section.value])
const endpoint=computed(()=>({companies:'organizations',plans:'plans',payments:'invoices',documents:'legal',consents:'consents',access:'grants'})[section.value])
const bytes=v=>(Number(v||0)/1073741824).toLocaleString(locale.value==='ge'?'ka':locale.value,{maximumFractionDigits:2})+' GiB'
const name=p=>p?.terms?.names?.[locale.value]||p?.terms?.names?.en||p?.code
const money=(minor,currency)=>new Intl.NumberFormat(locale.value==='ge'?'ka':locale.value,{style:'currency',currency:currency||'KZT'}).format(Number(minor)/100)
const date=v=>v?new Date(v).toLocaleDateString(locale.value==='ge'?'ka':locale.value):'—'
const status=v=>t('adminPortal.statuses.'+(v||'none'))
function cells(row){switch(section.value){
 case 'companies':return [row.name,row.email,row.is_verified?status('verified'):status('pending'),row.users_count,row.companies_count,row.plan_code||'—',bytes(row.used_bytes),status(row.subscription_status),date(row.created_at)]
 case 'plans':return [row.code,name(row),row.version,status(row.status),money(row.terms.price_minor,row.terms.currency),t('adminPortal.'+(row.is_public?'publicPlan':'internalPlan'))]
 case 'payments':return [row.number||'#'+row.id,row.company_id,status(row.status),money(row.total_minor,row.currency),date(row.due_date)]
 case 'documents':return [row.title,t('adminPortal.'+row.type),row.locale.toUpperCase(),row.version,status(row.status),date(row.effective_at)]
 case 'consents':return [row.email,row.title,row.version,t('adminPortal.'+row.action),date(row.created_at)]
 default:return [row.email,row.permission,date(row.created_at)]}}
async function load(){const token=++revision;loading.value=true;error.value='';try{if(!overview.value)overview.value=(await api.get('/platform-admin/overview')).data;const params={page:page.value};if(section.value==='companies'){params.search=query.value;params.sort=sort.value;if(verified.value!=='')params.verified=verified.value}if(section.value==='consents')params.search=query.value;const data=(await api.get('/platform-admin/'+endpoint.value,{params,silent:true})).data;if(token!==revision)return;rows.value=data.data||[];total.value=data.total??rows.value.length;lastPage.value=data.last_page||1}catch(e){if(token===revision)error.value=e.data?.message||e.message||t('adminPortal.loadFailed')}finally{if(token===revision)loading.value=false}}
async function mutate(action){if(busy.value)return;busy.value=true;error.value='';try{await action();notice.value=t('adminPortal.saved');await load()}catch(e){error.value=e.data?.message||e.response?.data?.message||t('adminPortal.saveFailed')}finally{busy.value=false}}
async function open(row){if(section.value==='companies'){detail.value=(await api.get('/platform-admin/organizations/'+row.id)).data;await loadUsers();plans.value=(await api.get('/platform-admin/plans')).data.data.filter(p=>p.status==='published');assignVersion.value=detail.value.subscription?.plan_version_id||'';assignEnd.value=''}else if(section.value==='plans')editor.value={kind:'plan',data:row};else if(section.value==='documents'){editor.value={kind:'legal',data:(await api.get('/platform-admin/legal/'+row.id)).data.data}}}
async function loadUsers(){if(!detail.value)return;const data=(await api.get('/platform-admin/organizations/'+detail.value.organization.id+'/users',{params:{page:userPage.value}})).data;users.value=data.data;userLastPage.value=data.last_page}
async function create(kind){if(kind==='invoice')organizationOptions.value=(await api.get('/platform-admin/organizations',{params:{per_page:100}})).data.data;editor.value={kind,data:null}}
async function saveEditor(data){const e=editor.value;await mutate(async()=>{if(e.kind==='plan')await api.post('/platform-admin/plans',data);if(e.kind==='legal')await api.post('/platform-admin/legal',data);if(e.kind==='invoice')await api.post('/platform-admin/invoices',data);if(e.kind==='supplier')await api.put('/platform-admin/billing/supplier',data);if(e.kind==='buyer')await api.put('/platform-admin/organizations/'+detail.value.organization.id+'/billing',data);editor.value=null;if(detail.value)detail.value=(await api.get('/platform-admin/organizations/'+detail.value.organization.id)).data})}
async function openProofs(invoice){proofs.value={invoice,rows:(await api.get('/platform-admin/invoices/'+invoice.id+'/proofs')).data.data}}
async function uploadAsset(item){if(!item.file)return;await mutate(async()=>{const data=new FormData();data.append('asset',item.file);if(item.approved)data.append('approved','1');await api.post('/platform-admin/billing/assets/'+item.kind,data)})}
async function pdf(kind,id,preview=false){const tab=window.open('about:blank','_blank');if(tab)tab.opener=null;try{const data=(await api.get('/platform-admin/'+kind+'/'+id+'/pdf',{params:{preview},responseType:'blob',silent:true})).data;const url=URL.createObjectURL(data);if(tab)tab.location=url;else{const link=document.createElement('a');link.href=url;link.download=kind+'-'+id+'.pdf';link.click()}setTimeout(()=>URL.revokeObjectURL(url),60000)}catch{tab?.close();error.value=t('adminPortal.loadFailed')}}
function ask(label,action,approval=false){approvalNote.value='';confirmation.value={label,action,approval}}
async function confirm(){const c=confirmation.value;await mutate(async()=>{await c.action();confirmation.value=null})}
watch([()=>route.params.section],()=>{page.value=1;query.value='';load()},{immediate:true})
watch([query,verified,sort],()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;load()},300)})
onBeforeUnmount(()=>{revision++;clearTimeout(searchTimer)})
</script>
<template><div class="admin-layout"><Sidebar is-sub-sidebar><router-link to="/" class="admin-logo"><MroBrand /></router-link><span class="muted">{{t('adminPortal.platform')}}</span><MenuItem v-for="s in sections" :key="s[0]" :title="t('adminPortal.'+s[0])" :icon="s[2]" :route="'/admin/'+s[0]" :active="section===s[0]" /><div class="admin-spacer"></div><ThemeSwitcher /><MenuItem :title="t('adminPortal.portal')" icon="Dashboard" :route="{name:'home'}" /></Sidebar>
<main class="admin-main"><header><div><p class="muted">{{t('adminPortal.platform')}}</p><h1>{{title}}</h1></div><div class="actions"><Button v-if="section==='plans'&&permission('plans.write')" :text="t('adminPortal.createPlan')" @click="create('plan')" /><Button v-if="section==='documents'&&permission('legal.write')" :text="t('adminPortal.createDocument')" @click="create('legal')" /><Button v-if="section==='payments'&&permission('billing.write')" :text="t('adminPortal.createInvoice')" @click="create('invoice')" /><Button v-if="section==='payments'&&permission('billing.write')" color="secondary" :text="t('adminPortal.supplier')" @click="async()=>{supplier=(await api.get('/platform-admin/billing/supplier')).data.data;editor={kind:'supplier',data:supplier}}" /></div></header>
<p v-if="overview && ['plans','payments','companies'].includes(section)" class="admin-notice">{{t('adminPortal.commercialDisabled')}}</p><p v-if="section==='documents'" class="admin-notice">{{t('adminPortal.legalDraftNotice')}}</p><p v-if="error" role="alert" class="admin-error">{{error}}</p><p v-if="notice" role="status" class="muted">{{notice}}</p>
<div class="admin-toolbar"><TextInput v-if="['companies','consents'].includes(section)" v-model="query" :placeholder="t('adminPortal.search')" :aria-label="t('adminPortal.search')" /><Select v-if="section==='companies'" v-model="verified" :options="[{id:'',name:t('adminPortal.all')},{id:1,name:status('verified')},{id:0,name:status('pending')}]" value-key="id" /><Select v-if="section==='companies'" v-model="sort" :options="['created_at','name','users_count','companies_count'].map(id=>({id,name:t('adminPortal.sort_'+id)}))" value-key="id" /><span class="muted">{{total}}</span></div>
<form v-if="section==='access'" class="actions" @submit.prevent="mutate(()=>api.post('/platform-admin/grants',{user_id:grantUser,permission:grantPermission}))"><TextInput v-model="grantUser" type="number" :placeholder="t('adminPortal.userId')" required /><Select v-model="grantPermission" :options="['platform.manage','companies.read','users.write','plans.read','plans.write','subscriptions.write','billing.read','billing.write','legal.read','legal.write','legal.approve','legal.publish'].map(id=>({id,name:id}))" value-key="id" /><Button type="submit" :text="t('adminPortal.grant')" :disabled="busy" /></form>
<div class="admin-table-scroll" :aria-busy="loading"><SharedTable ><template #header><tr><th v-for="h in heading" :key="h">{{t('adminPortal.'+h)}}</th><th>{{t('adminPortal.actions')}}</th></tr></template><tr v-for="row in rows" :key="row.id"><td v-for="(cell,i) in cells(row)" :key="i" :data-column="heading[i]"><button v-if="section==='companies'&&i===0" class="admin-name-link" @click="open(row)">{{cell}}</button><template v-else>{{cell}}</template></td><td><div class="actions"><Button v-if="['companies','plans','documents'].includes(section)" size="small" color="secondary" :text="t('adminPortal.'+(section==='companies'?'open':'newVersion'))" @click="open(row)" />
<template v-if="section==='plans'&&permission('plans.write')"><Button v-if="row.status==='draft'" size="small" :text="t('adminPortal.publish')" @click="ask(t('adminPortal.publish'),()=>api.put('/platform-admin/plans/'+row.id+'/status',{status:'published'}))" /><Button v-if="row.status==='published'" size="small" color="secondary" :text="t('adminPortal.archive')" @click="ask(t('adminPortal.archive'),()=>api.put('/platform-admin/plans/'+row.id+'/status',{status:'archived'}))" /></template>
<template v-if="section==='payments'"><Button size="small" color="secondary" :text="t('adminPortal.paymentProofs')" @click="openProofs(row)" /><Button size="small" color="secondary" :text="t('adminPortal.preview')" @click="pdf('invoices',row.id,row.status==='draft')" /><Button v-if="row.status==='draft'&&permission('billing.write')" size="small" :text="t('adminPortal.issue')" :disabled="!overview?.flags.invoice_issuance_enabled" @click="ask(t('adminPortal.issue'),()=>api.put('/platform-admin/invoices/'+row.id+'/status',{status:'issued'}))" /><Button v-if="['issued','awaiting_payment','overdue'].includes(row.status)&&permission('billing.write')" size="small" color="secondary" :text="t('adminPortal.cancel')" @click="ask(t('adminPortal.cancel'),()=>api.put('/platform-admin/invoices/'+row.id+'/status',{status:'cancelled'}))" /></template>
<template v-if="section==='documents'"><Button size="small" color="secondary" text="PDF" @click="pdf('legal',row.id)" /><Button v-if="row.status==='draft'&&permission('legal.approve')" size="small" :text="t('adminPortal.approve')" @click="ask(t('adminPortal.approve'),()=>api.put('/platform-admin/legal/'+row.id+'/status',{status:'approved',approval_note:approvalNote}),true)" /><Button v-if="row.status==='approved'&&permission('legal.publish')" size="small" :text="t('adminPortal.publish')" :disabled="!overview?.flags.legal_publication_enabled" @click="ask(t('adminPortal.publish'),()=>api.put('/platform-admin/legal/'+row.id+'/status',{status:'published'}))" /></template>
<Button v-if="section==='access'" size="small" color="secondary" :text="t('adminPortal.revoke')" @click="ask(t('adminPortal.revoke'),()=>api.delete('/platform-admin/grants/'+row.id))" /></div></td></tr><tr v-if="!rows.length"><td :colspan="(heading?.length||1)+1">{{t('adminPortal.'+(loading?'loading':'empty'))}}</td></tr></SharedTable></div>
<nav class="admin-pagination" :aria-label="t('adminPortal.pages')"><Button color="secondary" :text="t('adminPortal.previous')" :disabled="page<=1||loading" @click="page--;load()" /><span>{{page}} / {{lastPage}}</span><Button color="secondary" :text="t('adminPortal.next')" :disabled="page>=lastPage||loading" @click="page++;load()" /></nav>
</main>
<Modal v-if="detail&&!editor" :title="detail.organization.name" width="46" @modalClosed="detail=null;userPage=1"><div class="editor"><dl class="detail-grid"><dt>{{t('adminPortal.organization')}}</dt><dd>{{detail.organization.name}} · {{detail.organization.subdomain}}</dd><dt>{{t('adminPortal.plan')}}</dt><dd>{{detail.subscription?.snapshot?.terms?.names?.[locale]||detail.subscription?.snapshot?.code||'—'}}</dd><dt>{{t('adminPortal.status')}}</dt><dd>{{status(detail.subscription?.status)}}</dd></dl><section><h3>{{t('adminPortal.companies')}}</h3><ul><li v-for="c in detail.companies" :key="c.id">{{c.name}} — {{bytes(c.used_bytes)}} / {{bytes(c.technical_limit_bytes)}}</li></ul></section><section v-if="permission('subscriptions.write')"><h3>{{t('adminPortal.assignPlan')}}</h3><Select v-model="assignVersion" :options="plans.map(p=>({id:p.id,name:name(p)+' · v'+p.version}))" value-key="id" /><label>{{t('adminPortal.endsAt')}}<TextInput v-model="assignEnd" type="datetime-local" /></label><Button :text="t('adminPortal.assignPlan')" :disabled="!assignVersion||busy" @click="ask(t('adminPortal.assignPlan'),async()=>{await api.put('/platform-admin/organizations/'+detail.organization.id+'/subscription',{plan_version_id:assignVersion,ends_at:assignEnd||null});detail=(await api.get('/platform-admin/organizations/'+detail.organization.id)).data})" /></section>
<section><h3>{{t('adminPortal.users')}}</h3><div class="admin-table-scroll"><SharedTable ><template #header><tr><th>{{t('adminPortal.email')}}</th><th>{{t('adminPortal.roles')}}</th><th>{{t('adminPortal.verified')}}</th><th></th></tr></template><tr v-for="u in users" :key="u.id"><td>{{u.email}}</td><td>{{u.roles.map(r=>r.name).join(', ')}}</td><td>{{status(u.verification_status)}}</td><td><Button v-if="!u.is_verified&&permission('users.write')" size="small" color="secondary" :text="t('adminPortal.resend')" :disabled="busy" @click="ask(t('adminPortal.resend'),()=>api.post('/platform-admin/organizations/'+detail.organization.id+'/users/'+u.id+'/resend'))" /></td></tr></SharedTable></div><div class="actions"><Button color="secondary" :text="t('adminPortal.previous')" :disabled="userPage<=1" @click="userPage--;loadUsers()" /><span>{{userPage}} / {{userLastPage}}</span><Button color="secondary" :text="t('adminPortal.next')" :disabled="userPage>=userLastPage" @click="userPage++;loadUsers()" /></div></section>
<Button v-if="permission('billing.write')" color="secondary" :text="t('adminPortal.buyer')" @click="editor={kind:'buyer',data:detail.billing_profile}" /><section><h3>{{t('adminPortal.history')}}</h3><ul class="audit-list"><li v-for="a in detail.audit" :key="a.id">{{date(a.created_at)}} · {{a.action}} · #{{a.actor_id||'—'}}</li></ul></section></div></Modal>
<Modal v-if="editor" :title="t('adminPortal.editor_'+editor.kind)" width="46" @modalClosed="editor=null"><p v-if="error" role="alert" class="admin-error">{{error}}</p><PlanEditor v-if="editor.kind==='plan'" :plan="editor.data" :modules="overview.modules" :busy="busy" @save="saveEditor" /><BillingEditor v-if="['supplier','buyer'].includes(editor.kind)" :profile="editor.data" :assets="editor.kind==='supplier'" :busy="busy" @asset="uploadAsset" @save="saveEditor" /><LegalEditor v-if="editor.kind==='legal'" :document="editor.data" :busy="busy" @save="saveEditor" /><InvoiceEditor v-if="editor.kind==='invoice'" :organizations="organizationOptions" :busy="busy" @save="saveEditor" /></Modal>
<Modal v-if="proofs" :title="t('adminPortal.paymentProofs')" width="46" @modalClosed="proofs=null"><div class="editor"><p v-if="!proofs.rows.length">{{t('adminPortal.empty')}}</p><div v-for="p in proofs.rows" :key="p.id"><p>#{{p.id}} · {{status(p.status)}} · {{date(p.created_at)}}</p><a :href="api.defaults.baseURL+'/platform-admin/proofs/'+p.id+'/file'" target="_blank" rel="noopener">{{t('adminPortal.download')}}</a><p v-if="p.review_note">{{p.review_note}}</p><div v-if="p.status==='pending'&&permission('billing.write')" class="actions"><Button v-for="state in ['approved','rejected']" :key="state" :text="status(state)" :disabled="!overview.flags.billing_enabled" @click="ask(status(state),async()=>{await api.put('/platform-admin/proofs/'+p.id+'/review',{status:state,note:approvalNote});await openProofs(proofs.invoice)},true)" /></div></div></div></Modal>
<Modal v-if="confirmation" :title="confirmation.label" @modalClosed="confirmation=null"><p>{{t('adminPortal.confirmAction')}}</p><TextInput v-if="confirmation.approval" v-model="approvalNote" :placeholder="t('adminPortal.approvalReference')" /><p v-if="error" role="alert">{{error}}</p><div class="actions"><Button :text="t('adminPortal.confirm')" :disabled="busy || confirmation.approval&&approvalNote.trim().length<10" @click="confirm" /><Button color="secondary" :text="t('adminPortal.cancel')" @click="confirmation=null" /></div></Modal>
</div></template>
<style>
.admin-layout{display:flex;min-height:100dvh;height:100dvh;background:var(--surface-base);color:var(--text-base)}.admin-logo{padding:16px 8px}.admin-spacer{flex:1}.admin-main{padding:32px;flex:1;min-width:0;overflow:auto}.admin-main header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}.admin-main h1{font-size:28px;margin:8px 0;font-weight:500}.admin-notice{border:1px solid var(--border-base);border-radius:12px;padding:12px 16px;margin:20px 0;color:var(--text-weak);line-height:1.5}.admin-toolbar{display:flex;align-items:center;gap:12px;margin:24px 0;flex-wrap:wrap}.admin-toolbar>.text-input{max-width:320px}.admin-toolbar .select-wrapper{max-width:250px}.admin-table-scroll{overflow:auto;border:1px solid var(--border-base);border-radius:12px}.admin-table-scroll table{border-collapse:collapse;width:100%;min-width:600px;font-size:13px}.admin-table-scroll th,.admin-table-scroll td{padding:12px 14px;text-align:left;border-bottom:1px solid var(--border-base);font-weight:400;vertical-align:middle;max-width:300px;overflow-wrap:anywhere}.admin-table-scroll th{color:var(--text-weak);white-space:nowrap}.admin-table-scroll tbody tr:hover{background:var(--surface-raised)}.admin-pagination{display:flex;align-items:center;justify-content:flex-end;gap:16px;margin-top:20px}.admin-layout .actions,.editor .actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.muted{color:var(--text-weak);font-size:13px}.admin-error{color:#c93846;padding:10px 0;overflow-wrap:anywhere}.editor{display:flex;flex-direction:column;gap:18px;max-height:75dvh;overflow:auto;padding:4px;min-width:0}.editor .form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.editor label{display:flex;flex-direction:column;gap:7px;font-size:13px;min-width:0}.editor textarea{box-sizing:border-box;width:100%;border:1px solid var(--border-base);border-radius:8px;padding:12px;font:inherit;background:var(--surface-base);color:var(--text-base);resize:vertical}.editor fieldset{border:1px solid var(--border-base);border-radius:10px;padding:14px}.editor h3{font-size:16px;font-weight:500}.detail-grid{display:grid;grid-template-columns:130px 1fr;gap:10px}.detail-grid dt{color:var(--text-weak)}.detail-grid dd{margin:0;overflow-wrap:anywhere}.audit-list{padding-left:20px;font-size:12px;line-height:1.8}.modal__window:has(.editor){max-width:calc(100vw - 16px);box-sizing:border-box}@media(max-width:700px){.admin-layout{display:block;height:auto}.admin-layout .sidebar{width:100%;height:auto;min-width:0;flex-direction:row;flex-wrap:wrap}.admin-logo{max-width:140px}.admin-layout .sidebar .menu-item{width:auto}.admin-main{padding:20px 12px}.admin-main header{align-items:flex-start;flex-direction:column}.editor .form-grid{grid-template-columns:1fr}.detail-grid{grid-template-columns:1fr}.admin-pagination{justify-content:center}}

.admin-layout>.sidebar{flex:0 0 260px;width:260px}.admin-logo{display:flex;align-items:center;width:100%;box-sizing:border-box;padding:18px 16px}.admin-logo>*{max-width:190px;min-width:0}.admin-logo svg,.admin-logo img{display:block;width:auto;max-width:190px;height:auto;max-height:44px}.admin-table-scroll td{min-width:105px}.admin-table-scroll td[data-column="email"]{min-width:220px;white-space:nowrap;overflow-wrap:normal}.admin-table-scroll td[data-column="organization"]{min-width:180px}.admin-name-link{border:0;background:transparent;color:var(--text-base);padding:0;font:inherit;text-align:left;text-decoration:underline;text-underline-offset:3px;cursor:pointer}.admin-name-link:focus-visible{outline:2px solid #069bdd;outline-offset:4px}
@media(max-width:700px){.admin-layout>.sidebar{width:100%!important;max-width:none!important;flex-basis:auto;min-height:0;position:static;box-sizing:border-box;gap:6px}.admin-logo{width:100%;max-width:none;flex:0 0 100%;padding:12px}.admin-logo svg,.admin-logo img{max-width:160px;max-height:34px}.admin-layout>.sidebar .menu-item{flex:0 1 calc(50% - 6px);width:calc(50% - 6px);min-width:0;font-size:13px}.admin-layout>.sidebar .admin-spacer{display:none}.admin-table-scroll th:first-child,.admin-table-scroll td:first-child{position:sticky;left:0;background:var(--surface-base);z-index:1}}
</style>
